cd /home/admin1/server-core && python3 - <<'PY'
import json,pathlib,stat,urllib.request,urllib.error,re
from pathlib import Path
manifest=Path('/home/admin1/server-core/operations/cloudflare-account.json')
mcp=Path('/home/admin1/.cursor/mcp.json')
if manifest.is_file():
 try:
  x=json.loads(manifest.read_text())
  ok=x.get('secret_id')=='cf-account-api' and x.get('consumer')=='g-ace-workspace'
  print('CLOUDFLARE_API_CONTRACT='+('PASS' if ok else 'NOT_VERIFIED'))
 except Exception: print('CLOUDFLARE_API_CONTRACT=NOT_VERIFIED')
else: print('CLOUDFLARE_API_CONTRACT=ABSENT')
if mcp.is_file() and not mcp.is_symlink():
 try:
  f=json.loads(mcp.read_text())
  c=f.get('mcpServers',{}).get('cloudflare-api',{})
  ok=isinstance(c,dict) and c.get('url')=='https://mcp.cloudflare.com/mcp'
  print('CLOUDFLARE_MCP_CONFIG='+('PASS' if ok else 'NOT_VERIFIED'))
  print('CLOUDFLARE_MCP_AUTH_MODE='+('OAUTH_CONFIG' if ok and isinstance(c.get('auth'),dict) else 'NOT_VERIFIED'))
 except Exception: print('CLOUDFLARE_MCP_CONFIG=NOT_VERIFIED')
else: print('CLOUDFLARE_MCP_CONFIG=ABSENT')
p=Path('/home/admin1/.config/libral-vault/internal-token')
if not p.is_file() or p.is_symlink() or p.stat().st_mode & 0o077:
 print('VAULT_TOKEN_FILE=NOT_READY')
 raise SystemExit(0)
print('VAULT_TOKEN_FILE=SAFE')
secret=p.read_text(encoding='utf-8').strip()
if len(secret)<24:
 print('VAULT_AUTH=NOT_READY')
 raise SystemExit(0)
base='http://127.0.0.1:8791/internal/v1/actions/http'
for name in ('g-acebot.jp','g-acebot.com'):
 data={'secret_id':'cf-account-api','consumer':'g-ace-workspace',
 'url':'https://api.cloudflare.com/client/v4/zones?name='+name,
 'method':'GET','secret_header':'authorization','secret_prefix':'Bearer '}
 req=urllib.request.Request(base,data=json.dumps(data).encode(),
 headers={'Authorization':'Bearer '+secret,'Content-Type':'application/json'},
 method='POST')
 label='JP' if name.endswith('.jp') else 'COM'
 try:
  with urllib.request.urlopen(req,timeout=12) as response: v=json.load(response)
  provider=v.get('provider',{}) if isinstance(v,dict) else {}
  api=json.loads(provider.get('body','{}'))
  if not provider.get('ok') or not api.get('success'):
   print('CLOUDFLARE_'+label+'_ZONE=API_REJECTED')
  else:
   rows=api.get('result',[])
   found=[z for z in rows if isinstance(z,dict) and z.get('name')==name]
   print('CLOUDFLARE_'+label+'_ZONE='+('FOUND_'+str(len(found)) if found else 'NOT_LISTED'))
   if found:
    print('CLOUDFLARE_'+label+'_STATUS='+('ACTIVE' if all(z.get('status')=='active' for z in found) else 'NOT_ACTIVE_OR_UNKNOWN'))
 except urllib.error.HTTPError as e:
  try:
   body=json.loads(e.read(4000))
   code=(body.get('error') or {}).get('code','HTTP_'+str(e.code))
   if not re.fullmatch(r'[A-Z0-9_]{3,60}',str(code)): code='HTTP_'+str(e.code)
  except Exception: code='HTTP_'+str(e.code)
  print('CLOUDFLARE_'+label+'_ZONE=VAULT_'+str(code))
 except Exception: print('CLOUDFLARE_'+label+'_ZONE=TRANSPORT_NOT_VERIFIED')
PY
